package cn.local.gaokao;

import android.app.*;
import android.os.*;
import android.content.*;
import android.database.Cursor;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Runs only in an isolated cn.local.gaokao sandbox on Wenyan/5556. */
public final class UnifiedInstrumentation extends Instrumentation {
    MainActivity a;int checks;
    void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    void ui(Runnable action){runOnMainSync(action);waitForIdleSync();SystemClock.sleep(650);}
    View tag(View v,String tag){if(tag.equals(v.getTag()))return v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){View found=tag(((ViewGroup)v).getChildAt(n),tag);if(found!=null)return found;}return null;}
    TextView find(View v,String value){if(v instanceof TextView&&value.equals(((TextView)v).getText().toString()))return (TextView)v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){TextView found=find(((ViewGroup)v).getChildAt(n),value);if(found!=null)return found;}return null;}
    View described(View v,String desc){if(desc.equals(String.valueOf(v.getContentDescription())))return v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){View found=described(((ViewGroup)v).getChildAt(n),desc);if(found!=null)return found;}return null;}
    void click(String value){ui(()->{TextView v=find(a.currentCanvas,value);check(v!=null,"visible action "+value);v.performClick();});}
    int count(StudyStore store,String table){try(Cursor c=store.getReadableDatabase().rawQuery("SELECT count(*) FROM "+table,null)){c.moveToFirst();return c.getInt(0);}}
    void shot(String name)throws Exception{android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();java.io.File dir=new java.io.File(a.getExternalFilesDir(null),"unified");dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    void runChecks()throws Exception{
        a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();SystemClock.sleep(700);
        ui(()->{a.setSubject("wenyan");a.home();});check(tag(a.currentCanvas,"home-check-in")!=null,"original top-right check-in exists");shot("01-home");
        check(tag(a.currentCanvas,"scene-quote")!=null,"original home quote retained");check(find(a.currentCanvas,"不背高考")==null&&find(a.currentCanvas,"设置")==null,"no replacement title or settings on home");
        View checkin=tag(a.currentCanvas,"home-check-in");check(checkin.getLayoutParams().width==a.dp(80)&&checkin.getLayoutParams().height==a.dp(42),"original check-in geometry 80 by 42 dp");
        check(a.dock.getChildCount()==1&&((android.view.ViewGroup)a.dock.getChildAt(0)).getChildCount()==2,"original two icon navigation");
        ui(a::library);check(find(a.currentCanvas,"我的内容")!=null,"original content hub");shot("09-content");
        ui(a::stats);check(tag(a.currentCanvas,"total-progress")!=null&&find(a.currentCanvas,"学习偏好")!=null,"original two-tab learning panel and progress");shot("08-statistics");
        ui(a::settings);check(find(a.currentCanvas,"个人记忆参数")!=null,"original preferences and trainer entry");shot("10-preferences");
        ui(()->new ProfilePanel(a).show());check(a.page.equals("profile"),"original profile page restored");shot("11-profile");
        ui(a::home);
        int first=Wallet.sign(a.commonStore,System.currentTimeMillis());check(first>0,"first check-in grants reward");for(String id:SubjectRules.IDS){ui(()->{a.setSubject(id);a.home();});check(Wallet.sign(a.commonStore,System.currentTimeMillis())==0,"one check-in across "+id);check(new CheckInStore(a).days().size()==1,"shared attendance across "+id);check(count(a.store,"events")==0,"home browsing cannot submit answers "+id);}
        ui(()->new CheckInCalendar(a).show(0));check(tag(a.currentCanvas,"check-in-month-card")!=null,"original full month calendar");check(!described(a.currentCanvas,"下个月").isEnabled(),"future month disabled");check(find(a.currentCanvas,"今")!=null&&find(a.currentCanvas,"今").getCurrentTextColor()==android.graphics.Color.WHITE,"signed today uses original white text");check(find(a.currentCanvas,"签到")==null,"calendar remains read-only");String month=((TextView)tag(a.currentCanvas,"check-in-month")).getText().toString();shot("12-calendar-current");ui(()->described(a.currentCanvas,"上个月").performClick());check(!month.equals(((TextView)tag(a.currentCanvas,"check-in-month")).getText().toString()),"previous month navigation");shot("13-calendar-previous");check(described(a.currentCanvas,"下个月").isEnabled(),"return month enabled");ui(()->described(a.currentCanvas,"下个月").performClick());check(month.equals(((TextView)tag(a.currentCanvas,"check-in-month")).getText().toString()),"next month returns to current");ui(()->described(a.currentCanvas,"返回").performClick());check(a.page.equals("stats")&&tag(a.currentCanvas,"total-progress")!=null,"calendar returns to original learning panel");check(new CheckInStore(a).days().size()==1,"calendar navigation never changes attendance");
        // Exact same ID in two databases is isolated, not silently deduplicated across subjects.
        ui(()->a.setSubject("wenyan"));a.store.getWritableDatabase().execSQL("INSERT INTO word_pass VALUES ('isolation-probe',2,1)");ui(()->a.setSubject("gushi"));check(a.store.wordPasses("isolation-probe")==0,"subject progress isolation");ui(()->a.setSubject("wenyan"));a.store.getWritableDatabase().delete("word_pass","id=?",new String[]{"isolation-probe"});
        for(String subject:new String[]{"wenyan","gushi"}){ui(()->a.setSubject(subject));String tid=a.textbookWords().getJSONArray("cards").getJSONObject(0).getJSONArray("contexts").getJSONObject(0).getString("text_id");ui(()->a.openWenyan("text",tid));check(a.page.equals("text")&&a.wenyanPanel!=null,"read native original in "+subject);check(count(a.store,"events")==0,"reading never submits in "+subject);shot("reader-"+subject);}
        ui(()->a.setSubject("wenyan"));
        int events=count(a.store,"events");ui(()->a.shell.books());check(find(a.currentCanvas,"分册学词")!=null,"native book shelf");shot("02-chinese-books");ui(()->a.shell.book("必修上"));check(count(a.store,"events")==events,"book browsing never scores");check(a.store.round(DailyPlan.KIND)==null,"book browsing never reserves plan");
        ui(()->{a.prefs.edit().putString("word_volume",WordVolumes.ALL).putString("word_text","").commit();a.openWords();});check(find(a.currentCanvas,"看释义")!=null,"wenyan uses meaning recall");shot("03-wenyan-question");click("看释义");TextView old=find(a.currentCanvas,"想对了");check(old!=null,"explicit meaning self-rating");ui(()->{old.performClick();old.performClick();});check(count(a.store,"events")==events+1,"double-tap commits once");check(count(a.store,"retrieval_evidence")==1,"answer evidence atomic");String oldFirst;try(Cursor c=a.store.getReadableDatabase().rawQuery("SELECT event FROM first_attempt LIMIT 1",null)){c.moveToFirst();oldFirst=c.getString(0);}check(oldFirst!=null,"first attempt retained");
        ui(()->{a.setSubject("gushi");a.prefs.edit().putString("word_volume",WordVolumes.ALL).putString("word_text","").commit();a.openWords();});check(tag(a.currentCanvas,"cloze-prompt")!=null,"recitation uses cloze");ui(()->((EditText)tag(a.currentCanvas,"cloze-input")).setText("默写草稿"));String snapshot=a.store.round(WordVolumes.kind(false,WordVolumes.ALL,""));check(snapshot.contains("默写草稿"),"draft persisted");int before=count(a.store,"events");ui(()->{a.home();a.setSubject("biology");a.home();a.setSubject("gushi");a.openWords();});check(((EditText)tag(a.currentCanvas,"cloze-input")).getText().toString().equals("默写草稿"),"draft survives subject switch");check(count(a.store,"events")==before,"draft and navigation never score");shot("04-recitation-question");click("揭晓原文");check(tag(a.currentCanvas,"recitation-answer")!=null,"recitation original after reveal");click("背出来了");check(count(a.store,"events")==before+1,"recitation score");try(Cursor c=a.store.getReadableDatabase().rawQuery("SELECT input,matched FROM retrieval_evidence LIMIT 1",null)){check(c.moveToFirst()&&c.getString(0).equals("默写草稿")&&c.getInt(1)==0,"raw input and objective mismatch separate from positive self-rating");}
        ui(()->{a.setSubject("biology");a.shell.books();});shot("05-biology-books");check(a.wordCardCount()==1121,"all approved biology cards included");ui(()->{a.prefs.edit().putString("word_volume",WordVolumes.ALL).putString("word_text","").commit();a.openWords();});check(tag(a.currentCanvas,"biology-prompt")!=null,"biology native question");check(tag(a.currentCanvas,"biology-answer")==null,"biology answer hidden");shot("06-biology-question");click("显示答案");check(tag(a.currentCanvas,"biology-answer")!=null,"biology answer shown after reveal");shot("07-biology-answer");click("良好");check(count(a.store,"events")==1,"biology one rating event");try(Cursor c=a.store.getReadableDatabase().rawQuery("SELECT passes FROM word_pass LIMIT 1",null)){check(c.moveToFirst()&&c.getInt(0)==4,"biology does not force four repeats");}
        JSONArray all=a.textbookWords().getJSONArray("cards");HashMap<String,String> seen=new HashMap<>();boolean siblings=false;JSONArray queue=SubjectRules.studyCards(a,WordVolumes.ALL,"",false);for(int n=0;n<queue.length();n++){JSONObject card=queue.getJSONObject(n);String note=card.getJSONObject("biology").getString("note_id");check(!seen.containsKey(note),"sibling note appears only once in biology queue");seen.put(note,card.getString("id"));}for(int n=0;n<all.length();n++)for(int k=0;k<n;k++)if(all.getJSONObject(n).getJSONObject("biology").getString("note_id").equals(all.getJSONObject(k).getJSONObject("biology").getString("note_id"))){siblings=true;break;}check(siblings,"real content has sibling clozes");
        ui(a::home);JSONObject backup=UnifiedBackup.snapshot(a);UnifiedBackup.validate(a,backup);String beforeRestore=backup.getJSONObject("subjects").toString();JSONObject corrupt=new JSONObject(backup.toString());JSONObject attempts=corrupt.getJSONObject("subjects").getJSONObject("gushi").getJSONObject("tables").getJSONObject("events");JSONArray rows=attempts.getJSONArray("rows");rows.put(new JSONArray(rows.getJSONArray(0).toString()));boolean rejected=false;try{UnifiedBackup.restore(a,corrupt);}catch(Exception expected){rejected=true;}check(rejected,"duplicate primary key rejects restore");check(UnifiedBackup.snapshot(a).getJSONObject("subjects").toString().equals(beforeRestore),"failed restore rolls back all subject databases");
        a.prefs.edit().putString("note:restore-test","temporary").commit();UnifiedBackup.restore(a,backup);check(!a.prefs.contains("note:restore-test"),"backup restores preferences");check(UnifiedBackup.snapshot(a).getJSONObject("subjects").toString().equals(beforeRestore),"backup roundtrip exact for tables and preferences");
        ui(()->a.shell.reviews());check(find(a.currentCanvas,"复习总览")!=null,"unified due review overview");ui(()->a.shell.stats());check(find(a.currentCanvas,"我的学习")!=null,"all-subject statistics");shot("08-statistics");
        ui(()->{a.setSubject("wenyan");a.home();});try(Cursor c=a.store.getReadableDatabase().rawQuery("SELECT event FROM first_attempt LIMIT 1",null)){check(c.moveToFirst()&&oldFirst.equals(c.getString(0)),"subject changes and restore preserve first response");}
    }
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();int code=-1;try{runChecks();result.putString("stream","PASS "+checks+" unified checks: three native subjects, original Wenyan UI and shared check-in, isolated progress, real book covers, hidden answers, draft and first-response retention, one-step biology FSRS, sibling avoidance, backup roundtrip and cross-database rollback.\n");}catch(Throwable e){code=0;result.putString("stream","FAIL after "+checks+": "+e+"\n");android.util.Log.e("GaokaoTest","Unified failure",e);}finish(code,result);}
}
